import heapq
from heapq import _heappop_max, _siftdown_max, _siftup_max

def _heappush_max(heap, item):
    heap.append(item)
    _siftdown_max(heap, 0, len(heap) - 1)

def _heappushpop_max(heap, item):
    if heap and item < heap[0]:
        item, heap[0] = heap[0], item
        _siftup_max(heap, 0)
    return item

def main():
    N, M = map(int, input().split())
    graph = [[] for _ in range(N)]
    for _ in range(M):
        l, d, k, c, a, b = map(int, input().split())
        a -= 1
        b -= 1
        graph[a].append((b, l, d, k, c))

    inf = float('inf')
    time = [-inf] * N
    time[N - 1] = inf
    queue = [(inf, N - 1)]

    while queue:
        tx, x = _heappop_max(queue)
        if time[x] < tx:
            for y, l, d, k, c in graph[x]:
                if tx < l + c:
                    continue
                if l + (k - 1) * d + c <= tx:
                    ty = l + (k - 1) * d
                else:
                    ty = tx - (tx - c - l) % d
                if time[y] < ty:
                    time[y] = ty
                    _heappush_max(queue, (ty, y))

    for i in range(N - 1):
        ans = time[i]
        if ans == -inf:
            ans = "Unreachable"
        print(ans)
